  "선택한 활동을 중심으로 시간대와 전체 예산에 맞춰 일정을 구성해요.": [
    "Build your schedule based on the time slots and total budget, centered on the activities you selected.",
    "以你选择的活动为中心，按时间段和总预算来安排行程。",
    "選んだアクティビティを中心に、時間帯と全体の予算に合わせてスケジュールを組み立てます。"
  ],
  "남는 시간과 예산에 맞춰 일정 채우기": [
    "Fill your schedule with leftover time and budget",
    "用剩余时间和预算把行程补满",
    "余った時間と予算でスケジュールを埋める"
  ],
  "선택한 활동을 먼저 담고, 여유가 있으면 놀거리·카페를 추가해요. 술집을 선택했다면 2차·3차도 이어갈 수 있어요. 예산이 부족하면 무료 산책을 넣을 수 있어요. 밤 8시 이후 카페는 자동으로 넣지 않아요.": [
    "First add the selected activities, and if you have extra time, add fun spots and cafes. If you choose a bar, you can also continue to the 2nd or 3rd round. If your budget is short, you can include free walks. Cafes after 8:00 PM are not added automatically.",
    "先加入你选择的活动；如果有余裕，再添加游玩点和咖啡馆。如果你选择了酒馆，也可以继续去第2段或第3段。若预算不足，也可以加入免费的散步。晚上8点之后的咖啡馆不会自动添加。",
    "選んだアクティビティを先に入れて、余裕があれば遊び場・カフェも追加します。酒場を選んだ場合は2次・3次も続けられます。予算が足りなければ無料の散策を入れることもできます。午後8時以降のカフェは自動では追加されません。"
  ],
  "예산이 부족하면 무료 산책도 허용": [
    "If your budget is short, free walks are also allowed",
    "若预算不足，也允许加入免费散步",
    "予算が足りない場合は無料の散策も許可"
  ],
  "시간이 남고, 남은 예산으로 유료 활동을 추가하기 어려울 때 주변 산책 장소를 찾아요.": [
    "When you have extra time and it’s hard to add paid activities with the remaining budget, look for nearby walking spots.",
    "当你还有空闲时间，并且用剩余预算很难再加入付费活动时，寻找附近适合散步的地方。",
    "時間が余っていて、残った予算では有料のアクティビティを追加しにくいときは、近くの散歩スポットを探します。"
  ],
  "예산은 예상 최저·최고 금액의 평균을 기준으로 맞춰요. 실제 주문에 따라 달라질 수 있어요.": [
    "Your budget is set based on the average of the estimated minimum and maximum amounts. It may vary depending on your actual orders.",
    "预算以预估最低与最高金额的平均为准来设定。实际点单可能会有所不同。",
    "予算は、見込みの最小額・最大額の平均を基準に設定します。実際の注文内容によって変わる可能性があります。"
  ],
