  "인원": [
    "People count",
    "人数",
    "人数"
  ],
  "식사·주류·활동비를 합친 예상 금액이에요. 등록된 장소는 메뉴 가격으로 예산을 확인해요. 주변에 등록된 장소가 없어 실시간 검색을 사용하면 가격 미확인 장소도 포함되며 총예산은 미검증으로 안내해요.": [
    "This is the estimated total amount including meals, alcoholic drinks, and activity costs. Budgets are checked using the menu prices for registered places. If there are no registered places nearby and you use real-time search, price-unconfirmed places are included and the total budget is shown as unverified.",
    "这是将餐食、酒类和活动费用合计后的预估金额。已注册的地点会以菜单价格来核对预算。若附近没有已注册地点、需要使用实时搜索，则也会包含价格未确认的地点，且总预算将以未验证的方式提示。",
    "食事・酒類・アクティビティ費用を合算した予想金額です。登録済みの場所はメニュー価格で予算を確認します。周辺に登録済みの場所がないためリアルタイム検索を使用すると、価格未確認の場所も含まれ、総予算は未検証として案内されます。"
  ],
  "반경 10km 안에서 자동차 이동 시간을 확인해요. 주차 여유는 장소마다 5분이며, 유류비·통행료·주차비는 예산에 포함하지 않아요.": [
    "Check driving time within a 10 km radius. Parking availability is 5 minutes per place, and fuel, tolls, and parking fees are not included in the budget.",
    "在10 km范围内确认汽车移动车程时间。每个地点的停车余裕为5分钟；燃油费、通行费和停车费不包含在预算中。",
    "半径10 km以内の自動車移動時間を確認します。駐車の余裕は場所ごとに5分で、燃料費・通行料・駐車料金は予算に含まれません。"
  ],
